const stop = new Set(['is','a','an','the','for','to','of','and','or','in','on','good','choice','should','i','my','with','building','build','are','be','it','this','that','how','do','does','can','use','using','best','vs','when','what','why','which','better','worth','as']);
const q = String($json.chatInput || '');
const keywords = q.toLowerCase().replace(/[^a-z0-9\s.+#-]/g, ' ').split(/\s+/).filter(w => w.length > 1 && !stop.has(w)).slice(0, 6).join(' ');
return { chatInput: q, keywords: keywords || q };

